    "ld_translation": "تميں سردي ني موسم نا شروع ما سردي سي بچو، انے يھ موسم نا اْخر ما اهني تلقي كرو، كيم كھ سردي ني موسم جسم ما وه مثل عمل كرے چھے جھ مثل جھاڑو ما يھ عمل كرے چھے، يھ موسم نو شروع جھاڑو نے جلاوي دے چھے انے اهنو اِخر اهنے سرسبز كري دے چھے. سردي ني موسم نا شروع ما جھاڑو نا پتھ ؤ سكھائي جائي چھے، انے اهنو رنگ لالاس انے پيلاس طرف مائل تھائي چھے، تھ بعد يھ پتھ ؤ جھاڑو پر سي گري جائي چھے.",
    "english_translation": "Protect yourselves at the onset of the cold season and embrace it at its end for the cold has the same effect on bodies that it has on trees. The arrival of the cold season burns trees ( causing their leaves to fall ) but the end revives them with fresh leaves. At the onset of autumn when temprature begins to drop , leaves of certain trees turn various hues of red and yellow they dry and eventually fall off.",
    "reference": "روضة هدايات 1",
    "arabic_normalized": "توقوا البرد في اوله وتلقوه في اخره فانه يعمل في الابدان كما يفعل في الاشجار اوله يحرق واخره يورق",
    "ld_normalized": "تميں سردي ني موسم نا شروع ما سردي سي بجو، انے يھ موسم نا اخر ما اهني تلقي كرو، كيم كھ سردي ني موسم جسم ما وه مثل عمل كرے جھے جھ مثل جھارو ما يھ عمل كرے جھے، يھ موسم نو شروع جھارو نے جلاوي دے جھے انے اهنو اخر اهنے سرسبز كري دے جھے. سردي ني موسم نا شروع ما جھارو نا بتھ ء سكھاءي جاءي جھے، انے اهنو رنك لالاس انے بيلاس طرف ماءل تھاءي جھے، تھ بعد يھ بتھ ء جھارو بر سي كري جاءي جھے.",
    "english_normalized": "protect yourselves at the onset of the cold season and embrace it at its end for the cold has the same effect on bodies that it has on trees. the arrival of the cold season burns trees ( causing their leaves to fall ) but the end revives them with fresh leaves. at the onset of autumn when temprature begins to drop , leaves of certain trees turn various hues of red and yellow they dry and eventually fall off.",
    "stated_by_normalized": "علي ابن ابي طالب ص ع"
