    "ld_normalized": "روزي بے قسم ني جھے: ايك روزي وه جھے جھ نے تميں طلب كرو جھو، انے ايك روزي وه جھے جھ تمنے طلب كرے جھے، بجھي تميں جو يھ روزي نے نھ بهنجو - تو يھ تمنے بهنجي جاسے، تو تميں تمارا اج ني فكر بر بورا ورس ني فكر (نو وزن) نھ اتھاء، كيم كھ خدا تعالي هر نوا دن ما تماري قسمه ما جھ روزي جھے - يھ تمنے ابسے، انے تماري روزي ني طرف كوءي شخص تمارا بهلے هركز نهيں بهنجے، انے كوءي غالب تھانار يھ روزي ليوا ما تمارا بر هركز غالب نهيں تھاءي، انے تمارا واسطے جھ مقدر جھے - يھ تماري طرف بهنجوا ما هركز تاخير نهيں كرے.",
