    "english_normalized": "the worthiest of all merits is to : reconcile with those who have severed relations with you, be generous to those who have deprived you, show kindness to those who have wronged you, forgive those who have treated you unjustly. reconcile: to restore friendly relations.",
    "stated_by_normalized": "رسول الله صلع"
