    "ld_normalized": "تميں ايم جانو كھ - مءمن واسطے مءمن بر كءينك حقوق واجب جھے، اهنے موكي ديوا ما كوءي رخصه نتھي، يھ كيا حقوق؟ كھ يھ مءمن مءمن ني هميشھ خير خواهي كرے، مءمن بلاوے تو اهنے جواب دے، مءمن نے بهتر ياري دے، مءمن ني غيبه تھاوا سي روكے، مءمن ني خطاء نے معاف كرے، مءمن نا عذر نے قبول كرے، مءمن ني حرمه نے جالوي راكھے، مءمن بيمار هوءي تو اهنے بريكوا نے جاءي، انے مءمن كذري جاءي تو اهنا جنازه نے كاندهو دے.",
    "english_normalized": "you should know that a mumin enjoys certain rights that his brother is obligated to honour. he should:always offer him sincere advice. respond to him whenever he calls him. assist him to the best of his ability. prevent others from backbiting him. forgive him his mistakes. accept his excuses.protect his honour. visit him when he is ill. be his pall bearer. enjoy: possess and benefit from. pall bearer: a person carrying a janaazah.",
    "stated_by_normalized": "سيدنا حاتم محيي الدين رض"
