    "ld_normalized": "تين شخص نے قيامه نا دن جهنم ني اك نهيں جھبے! وه شخص جھ بوتانا والدين ني طاعه نا كرنار جھے انے اهنا ساتھے بھلاءي نا كرنار جھے، وه بءيرو جھ بوتانا شوهر ني طاعه نا كرنارجھے، وه بنده جھ خدا تعالي نا حق انے اهنا مولي نا حق نے اداء نا كرنار جھے.",
    "english_normalized": "three people will remain untouched by hell fire on the day of qiyaamat: the one who obeys his parents and treats them with reverence and kindness, the woman who respects her husband's wishes, the servant who fulfils his obligations towards allah taala and his master.",
    "stated_by_normalized": "رسول الله صلع"
