    "ld_normalized": "زهد ني معني ا بے جمله سي حاصل تھاءي جھے، الله عز وجل فرماوے جھے كھ: اتنا واسطے كھ جھ تمنے فوت تھيو اهنا بر تميں بستاء نھ كرو، انے تمنے جھ ملو جھے اهنا سي تميں خوش نھ تھاء، جھ شخص جھ جيز كذري كءي اهنا بربستاء نھ كرے، انے اءنار جيز سي خوش نھ تھاءي - تو يھ شخص يھ زهد نا بے جھيرا نے بكري ليدا (بورے بورو زهد كيدو).",
