    "reference": "روضة هدايات 3",
    "arabic_normalized": "اصدقوا في قولكم وبروا في ايمانكم لاولياءكم واعداءكم وتواسوا باموالكم وتحابوا بقلوبكم وتصدقوا علي فقراءكم واجتمعوا علي امركم ولا تدخلوا غشا ولا خيانه علي احد ولا تشكوا بعد اليقين ولا ترجعوا بعد الاقدام جبنا",
