    "english_translation": "All reprehensible traits and ignoble character stem from a pride greed and envy. They give rise to all evil and every act of allah taala's disobediance. Reprehensible: deserving blame, ignoble : not honourable",
    "reference": "روضة هدايات 3",
    "arabic_normalized": "ان الكبر والحرص والحسد اصول وامهات لساءر الخصال المذمومه والاخلاق الرديءه المنتشءه منها الشرور والمعاصي كلها",
    "ld_normalized": "تمام بد خصلتو انے نيجا اخلاق نو اصل - مھوتايء، لالج انے حسد جھے، اهما سي سكلي خرابيو انے خدا تعالي ني بے فرماني نا عملوا بيدا تھاءي جھے.",
    "english_normalized": "all reprehensible traits and ignoble character stem from a pride greed and envy. they give rise to all evil and every act of allah taala's disobediance. reprehensible: deserving blame, ignoble : not honourable",
