    "english_normalized": "understand that your efforts in learning lisan al dawat, the language spoken by the dai of your time will bring about much barakaat in your lives. therefore all of you - men, women and children- should strive to attain proficiency in it, bearing in mind the plentiful hasanaat ( merits) and good fortune it entails.",
